            if let Some(syntax) = syntax_set.find_syntax_by_extension(token) {
                file_name_syntax = Some(SyntaxReferenceInSet { syntax, syntax_set });
                keep_searching_file_name = false;
            } else {
                let stripped_result =
                    try_with_stripped_suffix(current_ref, mapping.ignored_suffixes(), |stripped_file_name| {
                        Ok(Some(stripped_file_name.to_os_string()))
                    });
                if let Err(error) = stripped_result {
                    return Err(error);
                } else if let Ok(Some(stripped_name)) = stripped_result {
                    if stripped_name == current_file_name {
                        keep_searching_file_name = false;
                    } else if let Some(stripped_token) = stripped_name.to_str() {
                        if stripped_token == token {
                            keep_searching_file_name = false;
                        } else if token.starts_with(stripped_token) {
                            if stripped_name.len() < current_file_name.len() {
                                current_file_name = stripped_name;
                            } else {
                                keep_searching_file_name = false;
                            }
                        } else {
                            keep_searching_file_name = false;
                        }
